function lang(){const b=[...document.querySelectorAll('.lang-toggle button.active')][0];const x=(b?.textContent||'KO').trim().toUpperCase();return x==='EN'?'en':x==='JA'?'ja':x.includes('中文')?'zh':'ko'}
function c(){return C[lang()]||C.ko}function txt(el,v){if(el&&typeof v==='string'&&el.textContent!==v)el.textContent=v}function lastSpan(b){return b?.querySelector('span:last-child')}
function sidebar(){const n=document.querySelector('.petgrow-sidebar-nav-grouped');if(!n)return;const x=c(),sec=[...n.querySelectorAll(':scope>.sidebar-section-label')],btn=[...n.querySelectorAll(':scope>button')];[x.life,x.content,x.info].forEach((v,i)=>txt(sec[i],v));[x.home,x.pets,x.nearby,x.music,x.talk,x.bti,x.saju,x.tarot,x.tips,x.news,x.about].forEach((v,i)=>txt(lastSpan(btn[i]),v))}
function hamburger(){const p=document.querySelector('.ham-panel');if(!p)return;const x=c(),g=[...p.querySelectorAll('.ham-nav-group')],secs=[x.life,x.content,x.info],labs=[[x.pets,x.nearby,x.music],[x.talk,x.bti,x.saju,x.tarot],[x.tips,x.news,x.about]];g.forEach((a,i)=>{txt(a.querySelector('.ham-section-label'),secs[i]);[...a.querySelectorAll('.ham-nav-item')].forEach((b,j)=>txt(lastSpan(b),labs[i]?.[j]))});txt(lastSpan(p.querySelector('.ham-nav>.ham-nav-item')),x.home)}
function heroes(){const l=lang();if(l!=='ja'&&l!=='zh')return;document.querySelectorAll('.petgrow-unified-hero').forEach(h=>{const h1=h.querySelector('h1'),k=heroAliases[(h1?.textContent||'').trim()]||(h1?.textContent||'').trim(),v=H[l]?.[k];if(v){txt(h1,v[0]);txt(h.querySelector('p'),v[1])}})}
function home(){const r=document.querySelector('.petgrow-dashboard-home');if(!r)return;const x=c();txt(r.querySelector('.dash-welcome p'),x.desc);txt(r.querySelector('.dash-pet-copy>small'),x.today);const m=[...r.querySelectorAll('.dash-pet-metrics small')];[x.weight,x.gender,x.type].forEach((v,i)=>txt(m[i],v));[...r.querySelectorAll('.dash-section-head h2')].forEach(h=>{if(/자주 사용하는 메뉴|Quick access|よく使うメニュー|常用菜单/.test(h.textContent||''))txt(h,x.quick)});const q=[...r.querySelectorAll('.dash-quick-grid button')];[x.pets,x.music,x.news,x.nearby,x.talk,x.bti].forEach((v,i)=>txt(q[i]?.querySelector('span'),v))}
function selectedName(page){const direct=(page.querySelector('.feature-pet-name')?.textContent||'').trim();if(direct)return direct;const b=[...page.querySelectorAll('.feature-pet-picker button')],a=b.find(z=>parseFloat(getComputedStyle(z).opacity)>=.95)||b[0];return(a?.querySelector(':scope>span:last-child')?.textContent||'').trim()}
function featureCopy(){const x=c(),s=document.querySelector('.feature-page-saju');if(s){const n=selectedName(s)||x.pets,h=s.querySelector('.feature-module-shell h2.pet-user-name');if(h)txt(h,x.sajuTitle(n))}const t=document.querySelector('.feature-page-tarot'),stage=t?.querySelector('.pet-tarot-stage');if(stage){const n=selectedName(t)||x.pets;txt(stage.querySelector('.pet-daily-eyebrow'),x.tarotEye);txt(stage.querySelector(':scope>h2'),x.tarotTitle(n))}}
function tarotHead(){const p=document.querySelector('.feature-page-tarot'),stage=p?.querySelector('.pet-tarot-stage');if(!p||!stage)return;const bs=[...p.querySelectorAll('.feature-pet-picker button')],b=bs.find(z=>parseFloat(getComputedStyle(z).opacity)>=.95)||bs[0],name=selectedName(p);if(!name)return;const src=b?.querySelector('img')?.getAttribute('src')||'',emoji=(b?.querySelector('span span')?.textContent||'🐾').trim(),sig=`${name}|${src}|${emoji}`;let h=stage.querySelector('.pg-tarot-pet-head');if(h?.dataset.sig===sig)return;if(!h){h=document.createElement('div');h.className='pg-tarot-pet-head';h.innerHTML='<span class="pg-tarot-avatar"></span><strong></strong>';stage.prepend(h)}h.dataset.sig=sig;const a=h.querySelector('.pg-tarot-avatar');a.replaceChildren();if(src){const im=document.createElement('img');im.src=src;im.alt='';a.append(im)}else{const sp=document.createElement('span');sp.textContent=emoji;a.append(sp)}txt(h.querySelector('strong'),name)}
let wt=0;function wait(ms=1100){let o=document.querySelector('.pg-wait-overlay');if(!o){o=document.createElement('div');o.className='pg-wait-overlay';o.setAttribute('role','status');o.setAttribute('aria-live','polite');o.innerHTML='<div class="pg-wait-card"><span class="pg-wait-spinner"></span><b></b><small></small></div>';document.body.append(o)}const x=c();txt(o.querySelector('b'),x.wait);txt(o.querySelector('small'),x.waitDesc);clearTimeout(wt);wt=setTimeout(()=>o?.remove(),ms)}function clearWait(){clearTimeout(wt);document.querySelector('.pg-wait-overlay')?.remove()}
function resetSaju(){const p=document.querySelector('.feature-page-saju');if(!p)return;const b=[...p.querySelectorAll('button')].find(z=>/다시 보기|Try again|다른\s*Pet사주\s*보기|Back to Pet Saju|別の.*Pet|戻る|重新|返回/.test((z.textContent||'').trim()));if(b)b.click()}
function lastBti(p){const z=[...p.querySelectorAll('.bg-sub')].map(e=>(e.textContent||'').trim()).find(v=>/^\d+\s*\/\s*\d+$/.test(v));const m=z?.match(/^(\d+)\s*\/\s*(\d+)$/);return!!m&&+m[1]===+m[2]}
function all(){sidebar();hamburger();heroes();home();tarotHead();featureCopy()}
document.addEventListener('click',e=>{const t=e.target instanceof Element?e.target:null;if(!t)return;if(t.closest('.lang-toggle button'))setTimeout(all,50);if(t.closest('.feature-page-saju .feature-pet-picker button')){clearWait();setTimeout(()=>{resetSaju();all()},80)}if(t.closest('.feature-page-tarot .feature-pet-picker button'))setTimeout(all,80);const s=t.closest('.feature-page-saju button');if(s&&!s.closest('.feature-pet-picker')&&/기본\s*Pet사주|오늘의\s*펫운세|궁합\s*결과\s*보기|Basic Pet Saju|Today'?s Pet Fortune|See compatibility|Pet占い|Pet命理/.test(s.textContent||''))wait(1250);const b=t.closest('.feature-page-petbti button'),p=b?.closest('.feature-page-petbti');if(b&&p&&!b.closest('.feature-pet-picker')&&lastBti(p))wait(900)},true);
let raf=0;function schedule(){if(raf)return;raf=requestAnimationFrame(()=>{raf=0;all()})}const ob=new MutationObserver(schedule);function boot(){all();ob.observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});window.addEventListener('pageshow',schedule)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
